const base = $('Config').first().json;
const cfg = {};
for (const item of $input.all()) { if (item.json.key) cfg[String(item.json.key).trim()] = String(item.json.value ?? '').trim(); }
const now = new Date();
const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const dayNum = d.getUTCDay() || 7; d.setUTCDate(d.getUTCDate() + 4 - dayNum);
const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
const weekNo = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
const week = d.getUTCFullYear() + '-W' + String(weekNo).padStart(2, '0');
return [{ json: {
  spreadsheetId: base.spreadsheetId, workflowName: base.workflowName,
  approverEmail: cfg['recipients.approver'] || base.approverEmail, opsEmail: cfg['recipients.ops'] || base.opsEmail,
  repo: cfg['github.repo'] || base.repo, baseBranch: cfg['github.base'] || base.baseBranch, postsPath: cfg['posts.path'] || base.postsPath,
  siteUrl: cfg['site.url'] || base.siteUrl,
  perCategory: Number(cfg['limits.signals_per_category'] || 15), approvalHours: Number(cfg['limits.approval_hours'] || 48),
  today: now.toISOString().slice(0, 10), week, branch: 'blog/' + week.toLowerCase(),
  sheetUrl: 'https://docs.google.com/spreadsheets/d/' + base.spreadsheetId + '/edit'
} }];

const cfg = $('Build config').first().json;
const xml = String(($input.first().json || {}).data || '');
const slugs = Array.from(xml.matchAll(/\/blog\/([a-z0-9-]+)<\/loc>/g)).map(m => m[1]);
const existing_titles = slugs.map(s => s.replace(/-/g, ' '));
const since = Date.now() - 7 * 86400000;
const rows = $('Read Signals').all().map(i => i.json).filter(r => r && r.signal_id && r.category && Date.parse(r.collected_at || '') >= since);
const map = { disaster_alerts: 'For Displaced Families', furnished_housing_trends: 'Market Guides', furnished_housing_guides: 'For Displaced Families', furnished_finder_weekly: 'Market Guides' };
return Object.keys(map).map(category => {
  const signals = rows.filter(r => r.category === category).sort((a, b) => Number(b.score || 0) - Number(a.score || 0)).slice(0, cfg.perCategory)
    .map(r => ({ signal_id: r.signal_id, source: r.source, title: r.title, url: r.url, summary: r.summary, region: r.region, score: Number(r.score || 0), collected_at: r.collected_at }));
  return { json: { brief_id: cfg.week + ':' + category, week: cfg.week, today: cfg.today, category, blog_category: map[category], signals, existing_titles, existing_slugs: slugs, signal_count: signals.length } };
});

const inputs = $('Build brief prompts').all();
const extract = (j) => { if (!j) return ''; if (typeof j.output === 'string') return j.output; if (typeof j.output_text === 'string') return j.output_text; if (typeof j.text === 'string') return j.text; if (typeof j.content === 'string') return j.content;
  const walk = (v) => { if (typeof v === 'string') { if (v.trim().startsWith('{')) return v; return ''; } if (Array.isArray(v)) { for (const x of v) { const r = walk(x); if (r) return r; } return ''; } if (v && typeof v === 'object') { for (const k of ['text', 'content', 'output', 'message', 'value']) { if (v[k] !== undefined) { const r = walk(v[k]); if (r) return r; } } for (const k of Object.keys(v)) { const r = walk(v[k]); if (r) return r; } } return ''; };
  return walk(j); };
const parse = (s) => { try { return JSON.parse(s); } catch (e) { const m = String(s).match(/\{[\s\S]*\}/); return m ? JSON.parse(m[0]) : null; } };
return $input.all().map((item, i) => {
  const src = inputs[i] ? inputs[i].json : {};
  const brief = parse(extract(item.json)) || {};
  const join = (v) => Array.isArray(v) ? v.join(' | ') : String(v || '');
  return { json: {
    brief_id: src.brief_id, week: src.week, category: src.category, blog_category: src.blog_category,
    proposed_title: String(brief.proposed_title || ''), angle: String(brief.angle || ''), target_keywords: join(brief.target_keywords), outline: join(brief.outline),
    evidence_ids: join(brief.evidence_ids), why_now: String(brief.why_now || ''), risk_notes: String(brief.risk_notes || ''), status: 'pending', decided_at: '',
    _brief: { ...brief, category: src.category, blog_category: src.blog_category }, _signals: (src.signals || []).filter(s => !Array.isArray(brief.evidence_ids) || brief.evidence_ids.length === 0 || brief.evidence_ids.includes(s.signal_id)), _existing_slugs: src.existing_slugs || [], _today: src.today
  } };
});

const cfg = $('Build config').first().json;
const briefs = $('Parse briefs').all().map(i => i.json);
const lines = ['Hi William,', '', 'Here are this week\'s four proposed blog posts (' + cfg.week + '). Approve to have them written and opened as a pull request; decline to skip this week.', ''];
briefs.forEach((b, i) => {
  lines.push((i + 1) + '. ' + b.proposed_title + '  [' + b.blog_category + ']');
  lines.push('   Angle: ' + b.angle);
  lines.push('   Keywords: ' + b.target_keywords);
  lines.push('   Outline: ' + b.outline);
  lines.push('   Why now: ' + b.why_now);
  if (b.risk_notes) lines.push('   Notes: ' + b.risk_notes);
  lines.push('');
});
lines.push('Evidence and briefs: ' + cfg.sheetUrl);
lines.push('This request expires in ' + cfg.approvalHours + ' hours.');
return [{ json: { to: cfg.approverEmail, subject: 'Blog approval · ' + cfg.week + ' · 4 posts', message: lines.join('\n') } }];

