  return walk(j); };
const parse = (s) => { try { return JSON.parse(s); } catch (e) { const m = String(s).match(/\{[\s\S]*\}/); try { return m ? JSON.parse(m[0]) : null; } catch (e2) { return null; } } };
const CATS = ['For Insurance Professionals', 'For Displaced Families', 'Market Guides'];
const MOTIFS = ['ai', 'checklist', 'house', 'paw', 'key', 'magnifier', 'map', 'gears'];
const CTAS = ['housing', 'property', 'none'];
const DOMAINS = ['novahavens.com', 'weather.gov', 'fema.gov', 'census.gov', 'hud.gov', 'ready.gov', 'redcross.org'];
const FORBIDDEN = [
  { name: 'property count', re: /\b\d[\d,]*\+?\s+(properties|homes|listings)\b/i },
  { name: 'coverage claim', re: /\b(your|the)\s+policy\s+(covers|will cover|pays|reimburses)\b/i },
  { name: 'carrier/adjuster audience framing', re: /\b(for|dear)\s+(adjusters|carriers)\b/i },
];
const FAQ = '## Frequently Asked Questions';
function validate(post, existing) {
  const errors = [];
  const content = String(post.content || '').trim(); const title = String(post.title || ''); const excerpt = String(post.excerpt || ''); const keywords = Array.isArray(post.keywords) ? post.keywords : [];
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(post.slug || '')) errors.push('slug must be kebab-case'); if (existing.includes(post.slug)) errors.push('slug already exists');
  if (!title.trim()) errors.push('title is required'); if (title.length > 70) errors.push('title is ' + title.length + ' chars (max 70)');
  if (excerpt.length < 80 || excerpt.length > 160) errors.push('excerpt is ' + excerpt.length + ' chars (must be 80-160)');
  if (keywords.length < 3 || keywords.length > 8) errors.push('keywords has ' + keywords.length + ' items (must be 3-8)');
  if (!CATS.includes(post.category)) errors.push('category invalid'); if (post.motif !== undefined && !MOTIFS.includes(post.motif)) errors.push('motif invalid'); if (!CTAS.includes(post.cta)) errors.push('cta invalid');
  if (!content.startsWith('> ')) errors.push('content must start with a "> " quick-summary block');
  const qh2 = content.split('\n').filter(l => l.startsWith('## ') && l.trim().endsWith('?')).length; if (qh2 < 3) errors.push('content has ' + qh2 + ' "## ...?" headings (need at least 3)');
  const blocks = content.split(/\n\n+/); const faqIdx = blocks.findIndex(b => b.trim() === FAQ);
  if (faqIdx === -1) errors.push('content must end with a "' + FAQ + '" section'); else {
    if (blocks.slice(faqIdx + 1).some(b => b.startsWith('## '))) errors.push('FAQ must be the last section');
    let n = 0; for (const b of blocks.slice(faqIdx + 1)) { const ls = b.split('\n'); const f = (ls[0] || '').trim(); const a = ls.slice(1).join(' ').trim(); if (f.startsWith('**') && f.endsWith('**') && f.includes('?') && a) n++; }
    if (n < 3) errors.push('FAQ section has ' + n + ' question blocks (need at least 3)');
  }
  const wc = content.split(/\s+/).filter(t => /[A-Za-z0-9]/.test(t)).length; if (wc < 800 || wc > 1700) errors.push('word count is ' + wc + ' (must be 800-1700)');
  const mentions = (content.match(/Nova Havens/g) || []).length; if (mentions < 2) errors.push('"Nova Havens" appears ' + mentions + ' times (need at least 2)');
  if (!content.includes('(629) 401-0054') && !content.includes('/contact')) errors.push('content must include "(629) 401-0054" or a "/contact" link');
  const text = title + '\n' + excerpt + '\n' + content;
  for (const f of FORBIDDEN) { const m = f.re.exec(text); if (m) errors.push('forbidden ' + f.name + ': "' + m[0] + '"'); }
  for (const url of (text.match(/https?:\/\/[^\s)>\]"'`]+/gi) || [])) { let host = ''; try { host = new URL(url).hostname.toLowerCase(); } catch (e) {} if (!DOMAINS.some(d => host === d || host.endsWith('.' + d))) errors.push('link not on allow-list: ' + url); }
  for (const s of (Array.isArray(post.sources) ? post.sources : [])) { let host = ''; try { host = new URL(s.url).hostname.toLowerCase(); } catch (e) {} if (!DOMAINS.some(d => host === d || host.endsWith('.' + d))) errors.push('source not on allow-list: ' + s.url); }
  return { ok: errors.length === 0, errors, wordCount: wc };
}
return $input.all().map((item, i) => {
  const src = inputs[i] ? inputs[i].json : {};
  const post = parse(extract(item.json)) || {};
  const result = validate(post, src.existing_slugs || []);
  return { json: { ...src, post, valid: result.ok, errors: result.errors, word_count: result.wordCount } };
});

