const cfg = $('Build config').first().json;
const rows = $('Final gate: post rows').all().map(i => i.json);
return [{ json: { run_at: new Date().toISOString(), workflow: cfg.workflowName, status: rows.every(r => r._valid) ? 'ok' : 'partial', items: rows.filter(r => r._valid).length, notes: cfg.week + ' · ' + rows.map(r => r.slug + ':' + r.status).join(', ') } }];

